请原生千问对 #247 C1/C2修订做独立组件复核，实际作者OpenAI，原任务PLAN-PATCHGATE-ESCROW-20261023。版本43453cf7（完整hash写在下方）。输出不超过200中文字，JSON {verdict,finding,trigger,fix}，没有具体绕过则说明approve范围，不当整阶段批准。C1选Claude审计给出的(a)：共享GitHub账号不证明Claude/owner身份，PR材料咨询保留，从rollout机器门槛移除；仍有千问+豆包独立执行器密码签名，不代owner发评论，A2仍关闭keys=0。C2改target，BASE checkout只读，CLI也核event/ref/sha；collector仅accept run.event=target，并核精确EVENT/BASE/HEAD/PR平台step、App/run/job/attempt/check/注册workflow hash。C3把candidate verify workflow纳入bundle。请只报告可复现缺陷，不将未展示imports当不存在。代码:
export function rolloutApproved({config,registry,trust,runnerSha,runtimeBundleSha256,now=Date.now()}) {
  validateA2Config(config);
  if(config.enabled!==true||config.base_compare_and_swap_verified!==true||config.production_signing_keys_provisioned!==true||!validateExecutorRegistry({registry,trust})
    ||!SHA.test(runnerSha||'')||!HASH.test(runtimeBundleSha256||'')||config.runtime_bundle_sha256!==runtimeBundleSha256)return false;
  // Audit signatures live outside the bundle they authenticate. A source commit
  // is metadata, not a self-referential commit containing its own signature.
  const subject={task_id:TASK,phase:'A2',runtime_bundle_sha256:runtimeBundleSha256};
  const proofs=config.stage_audits.map(a=>authenticate(a,{trust,subject,role:'stage_review',now,maxAge:86400})).filter(a=>a?.payload.verdict==='approve'&&SHA.test(a.payload.reviewed_source_commit||'')&&HASH.test(a.payload.artifact_sha256||''));
  // Shared-account Claude PRs remain preserved advisory artifacts. Self-labels,
  // owner-looking comments or infrastructure signatures cannot add model votes.
  return config.required_stage_auditors.every(provider=>proofs.some(p=>p.provider===provider))&&new Set(proofs.map(p=>p.executor)).size>=2;
}


WORKFLOW:
name: PatchGate A2 trusted base checks (no merge)
on:
  pull_request_target:
    branches: [main]
    types: [opened, synchronize, reopened, ready_for_review]
permissions: {contents: read}
concurrency: {group: 'patchgate-a2-base-${{ github.event.pull_request.number }}', cancel-in-progress: false}
jobs:
  patchgate-a2-base-checks:
    # Bootstrap stays off until the BASE interpreter has been reviewed and merged.
    if: github.event_name == 'pull_request_target' && github.ref == 'refs/heads/main' && vars.PATCHGATE_A2_BASE_CHECKS_ENABLED == 'true' && github.event.pull_request.head.repo.full_name == github.repository && contains(fromJSON('["OWNER","MEMBER","COLLABORATOR"]'), github.event.pull_request.author_association)
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - uses: actions/checkout@v4
        # The entire executable/import/config tree is BASE, never PR checkout.
        with: {ref: '${{ github.sha }}', persist-credentials: false, fetch-depth: 0}
      - uses: actions/setup-node@v4
        with: {node-version: '22'}
      - name: 'EVENT=pull_request_target BASE=${{ github.sha }} HEAD=${{ github.event.pull_request.head.sha }} PR=${{ github.event.pull_request.number }}'
        run: node scripts/patchgate-a2-collect.mjs base-check "$RUNNER_TEMP/a2-base-check.json"
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: a2-base-check-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/a2-base-check.json
          retention-days: 30

